begin;
set local role authenticated;
select set_config('request.jwt.claim.sub','5a6fa4c4-5427-47fa-9835-d997fe81c7d5',true);
do $test$
declare t uuid='944597b6-9c46-4bef-998d-f19e23c4245b';c uuid;pr uuid;a uuid;b uuid;l uuid;lp uuid;site uuid;rule uuid;rid uuid;req uuid=gen_random_uuid();q jsonb;payload jsonb;blocked boolean=false;
begin
 select id into c from public.hub_objects where tenant_id=t and object_type='Customer' and status='active' limit 1;
 select id into pr from public.hub_objects where tenant_id=t and object_type='Project' and status='active' limit 1;
 select id into a from public.hub_objects where tenant_id=t and object_type='Article' and status='active' limit 1;
 select id into b from public.hub_orderportal_price_lists where tenant_id=t and scope='base';
 if b is null then b=public.hub_orderportal_catalog_add(t,'list','{"name":"QA STD","scope":"base"}');end if;
 l=public.hub_orderportal_catalog_add(t,'list',jsonb_build_object('name','QA Kund '||req,'scope','customer','targetId',c));
 lp=public.hub_orderportal_catalog_add(t,'list',jsonb_build_object('name','QA Projekt '||req,'scope','project','targetId',pr));
 site=public.hub_orderportal_catalog_add(t,'site',jsonb_build_object('name','QA Täkt '||req));
 perform public.hub_orderportal_catalog_add(t,'price',jsonb_build_object('listId',b,'articleId',a,'unit','qa-ton','salePrice',100,'validFrom','2026-10-01','validTo','2026-10-31'));
 q=public.hub_orderportal_quote(t,a,c,pr,'2026-10-02','qa-ton');
 if (q->'price'->>'sale_price')::numeric is distinct from 100 then raise exception 'base priority';end if;
 perform public.hub_orderportal_catalog_add(t,'price',jsonb_build_object('listId',l,'articleId',a,'unit','qa-ton','salePrice',110,'validFrom','2026-10-01','validTo','2026-10-31'));
 q=public.hub_orderportal_quote(t,a,c,pr,'2026-10-02','qa-ton');
 if (q->'price'->>'sale_price')::numeric is distinct from 110 then raise exception 'customer priority';end if;
 rule=public.hub_orderportal_catalog_add(t,'price',jsonb_build_object('listId',lp,'articleId',a,'unit','qa-ton','salePrice',120,'purchasePrice',50,'validFrom','2026-10-01','validTo','2026-10-31'));
 q=public.hub_orderportal_quote(t,a,c,pr,'2026-10-02','qa-ton');
 if (q->'price'->>'sale_price')::numeric is distinct from 120 then raise exception 'project priority';end if;
 perform public.hub_orderportal_catalog_add(t,'price',jsonb_build_object('listId',lp,'articleId',a,'pickupId',site,'unit','qa-ton','salePrice',130,'validFrom','2026-10-01','validTo','2026-10-31'));
 if public.hub_orderportal_quote(t,a,c,pr,'2026-10-02','qa-ton')->>'status'<>'site_required' then raise exception 'missing site guard';end if;
 q=public.hub_orderportal_quote(t,a,c,pr,'2026-10-02','qa-ton',site);
 if (q->'price'->>'sale_price')::numeric is distinct from 130 then raise exception 'site priority';end if;
 if public.hub_orderportal_quote(t,a,c,pr,'2026-11-02','qa-ton',site)->>'status'<>'missing' then raise exception 'date guard';end if;
 begin perform public.hub_orderportal_catalog_add(t,'price',jsonb_build_object('listId',lp,'articleId',a,'unit','qa-ton','salePrice',140,'validFrom','2026-10-15','validTo','2026-10-31'));exception when others then if sqlerrm='overlapping_price_period' then blocked=true;else raise;end if;end;
 if not blocked then raise exception 'overlap guard';end if;
 payload=jsonb_build_object('title','QA testpris','customerId',c,'projectId',pr,'status','Utkast','start','2026-10-01T07:00','end','2026-10-01T09:00','lines',jsonb_build_array(jsonb_build_object('id','qa-line','articleId',a,'label','QA Artikel','date','2026-10-02','unit','qa-ton','quantity',2,'price',120,'priceRuleId',rule)));
 rid=public.hub_orderportal_save(t,null,0,req,payload);
 if (select amount from public.hub_orderportal_orders o where o.id=rid)<>240 then raise exception 'sale sum';end if;
 if (select o.payload#>>'{lines,0,priceSnapshot,ruleId}' from public.hub_orderportal_orders o where o.id=rid)<>rule::text then raise exception 'snapshot missing';end if;
 if (select (o.payload#>>'{lines,0,purchasePrice}')::numeric from public.hub_orderportal_orders o where o.id=rid)<>50 then raise exception 'purchase missing';end if;
 perform public.hub_orderportal_retire_price(t,rule);
 perform public.hub_orderportal_save(t,rid,1,req,payload);
 blocked=false;
 begin perform public.hub_orderportal_save(t,null,0,gen_random_uuid(),payload);exception when others then if sqlerrm='price_context_changed' then blocked=true;else raise;end if;end;
 if not blocked then raise exception 'retired price on new order';end if;
 if not exists(select 1 from public.hub_orderportal_prices where id=rule and retired_at is not null and retired_by=auth.uid()) then raise exception 'retirement audit';end if;
 blocked=false;
 begin perform public.hub_orderportal_save(t,rid,2,req,payload||jsonb_build_object('projectId',''));exception when others then if sqlerrm='price_context_changed' then blocked=true;else raise;end if;end;
 if not blocked then raise exception 'changed project guard';end if;
 l=public.hub_orderportal_catalog_add(t,'list',jsonb_build_object('name','QA Konkurrerande '||req,'scope','project','targetId',pr));
 perform public.hub_orderportal_catalog_add(t,'price',jsonb_build_object('listId',l,'articleId',a,'pickupId',site,'unit','qa-ton','salePrice',160,'validFrom','2026-10-01','validTo','2026-10-31'));
 if public.hub_orderportal_quote(t,a,c,pr,'2026-10-02','qa-ton',site)->>'status'<>'ambiguous' then raise exception 'ambiguity guard';end if;
 perform set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
 if exists(select 1 from public.hub_orderportal_price_lists) or exists(select 1 from public.hub_orderportal_prices) then raise exception 'RLS failure';end if;
 blocked=false;
 begin perform public.hub_orderportal_catalog_add(t,'site','{"name":"Forbidden"}');exception when others then if sqlerrm='permission_denied' then blocked=true;else raise;end if;end;
 if not blocked then raise exception 'write auth failure';end if;
end $test$;
rollback;
select 'PASS: price hierarchy, site specificity, missing site, dates, overlap, immutable snapshot, separate purchase/sale, changed context, ambiguity and tenant authorization. All writes rolled back.' result;
